<?php require_once 'includes/admin_common.php'; $id=(int)($_GET['id']??$_POST['id']??0); if($id<1){flash('danger','Invalid user.');redirect_to('manage_ustads.php');}
$user=fetch_one('SELECT * FROM ustads WHERE id=?','i',[$id]); if(!$user){flash('danger','User not found.');redirect_to('manage_ustads.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $name=trim($_POST['name']??'');$username=trim($_POST['username']??'');$email=trim($_POST['email']??'');$class=trim($_POST['class']??'');$role=strtoupper(trim($_POST['role']??'TEACHER'));$pass=(string)($_POST['password']??'');$emailLocked=isset($_POST['email_locked'])?1:0; $dup=fetch_one('SELECT id FROM ustads WHERE (username=? OR email=?) AND id<>? LIMIT 1','ssi',[$username,$email,$id]); if($name===''||!preg_match('/^[A-Za-z0-9_.-]{3,50}$/',$username)||!filter_var($email,FILTER_VALIDATE_EMAIL)||($pass!==''&&strlen($pass)<8)||!in_array($role,['ADMIN','TEACHER'],true)){flash('danger','Please provide valid user details.');} elseif($dup){flash('warning','Username or email already exists.');} else { if($pass!==''){ $hash=password_hash($pass,PASSWORD_DEFAULT); execute_stmt('UPDATE ustads SET name=?,username=?,email=?,class=?,role=?,password=?,email_locked=? WHERE id=?','ssssssii',[$name,$username,$email,$class,$role,$hash,$emailLocked,$id]); } else { execute_stmt('UPDATE ustads SET name=?,username=?,email=?,class=?,role=?,email_locked=? WHERE id=?','sssssii',[$name,$username,$email,$class,$role,$emailLocked,$id]); } flash('success','User updated successfully.'); redirect_to('view_ustad.php?id='.$id); }}
layout_start('Edit User'); ?><div class="mb-4"><nav aria-label="breadcrumb"><ol class="breadcrumb"><li class="breadcrumb-item"><a href="manage_ustads.php">Dashboard</a></li><li class="breadcrumb-item active">Edit User</li></ol></nav><h2 class="fw-bold">Edit <?= e($user['name']) ?></h2></div><?php user_form($user,'edit_ustad.php'); layout_end();
